INSERT INTO `reports` (`id`, `title`, `category`, `content`, `date`, `author`, `published`, `created_at`, `updated_at`, `subcategory`) VALUES (1,'Wasserschaden KAT-Lager','einsatz','Am Sonntag, den 11.01.2026, um 13:03 Uhr wurden wir zu einem Wasserschaden im KAT-Lager der Feuerwehr Innsbruck alarmiert. Im Bereich eines Wasserzählers kam es zu einer Leckage, und das Lager des BFV Innsbruck-Stadt sowie die danebenliegenden Räume wurden ca. 5 cm hoch unter Wasser gesetzt. Mittels zwei Wassersaugern wurde der Wasserschaden beseitigt und das Lager des BFV ausgeräumt. Nach knapp einer Stunde konnten wir wieder zusammenräumen und in die Wache einrücken.','2026-01-11','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','technisch'),(2,'Brand Mehrfamilienhaus - Rauchentwicklung am Dach','einsatz','Das neue Jahr startete genau um Punkt 00:00 Uhr für die FF Reichenau, mit der ersten Alarmierung. Die Alarmmeldung lautete: Radetzkystraße 42, Rauchentwicklung Mehrfamilienhaus am Dach, näheres unbekannt. Die sich auf Bereitschaft befindliche Mannschaft rückte umgehend aus und konnte als Quelle für die Rauchentwicklung die Heizungsanlage des Hauses feststellen.\r\n\nKurz nach dem Einrücken, wurden wir zu einem Brandmeldalarm alarmiert, welcher sich als Fehlalarm herausstellte.\r\n\nNoch an der Einsatzstelle, erhielten wir den nächsten Einsatz und zwar den Brand einer Feuerwerksbatterie im Gutshofpark. Das Kommando arbeitete den BMA noch fertig ab, während die TLF Besatzung sich zum Einsatzort begab. Auf dem Weg dorthin wurde eine regungslose Person am Gehsteig liegend festgestellt. Die Erstversorgung und Betreuung übernahm die Besatzung des Gefahrgutfahrzeuges und das Kommando, während die TLF Besatzung weiter zum Brand anfuhr.\r\n\nNach dem Einrücken wurden wir vom Bereitschaftsoffizier der BF Innsbruck noch zur Bereitschaft auf der Wache angefordert. Die Bereitschaft konnte ohne weiteren Einsatz um 02:00 Uhr beendet werden. \r\n\nWir wünschen allen Bewohner der Stadt Innsbruck ein gutes neues Jahr und vor allem viel Gesundheit.\r\n\n\"UNSERE FREIZEIT FÜR IHRE SICHERHEIT\"\r\n\nHelmut PLANK, Kommandant','2026-01-01','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','brand'),(3,'Brand Wald - Nachalarmierung','einsatz','Am Sonntag kurz vor 12:00 Uhr Mittag wurden auch wir zum Waldbrand östlich der Höttinger Alm alarmiert. Es galt Kameraden der FF Zirl und FF Hungerburg am Planötzenhof zur Besetzung des Wasserbehälters, woraus die Hubschrauber das Wasser entnehmen, zu besetzen. Gegen 16:30 Uhr konnten die 5 Kameraden wieder in die Wache einrücken. \r\n\n \r\n\nBereits den 2. Tag waren 2 Kameraden von unserer Einheit zur Besetzung des Feuerwehreinsatzleitfahrzeuges am Gramartboden bzw. Planötzenhof im Einsatz. Am Montag werden wieder 2 Kameraden unserer Einheit das Feuerwehreinsatzleitfahrzeug gemeinsam mit Kameraden anderer FF Einheiten und der BF Innsbruck besetzen. \r\n\n \r\n\nHelmut PLANK, Kommandant','2025-12-28','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','brand'),(4,'Brand MFH Wohnung, Hochhaus','einsatz','Am 23.06.2025 kurz nach 21:00 Uhr wurden wir zur Unterstützung der Berufsfeuerwehr zu einem gemeldeten Wohnungsbrand im 11. Stock eines Hochhauses in der Andechsstraße alarmiert. Da wir gerade von einer Gemeinschaftsübung mit der FF Mühlau am Weg in die Wache waren, fuhren wir umgehend mit 4 Fahrzeugen zu der Einsatzörtlichkeit. Dort eingetroffen stellten wir einen Atemschutzreservetrupp. Der Brand konnte durch die BF rasch gelöscht werden. Ein abmontierter Küchenschrank wurde von uns im Freien noch nachgelöscht und wir konnten nach ca. 45 Minuten wieder abrücken. An der Küche entsand großer Sachschaden. Nach dem Einrücken wurden noch die Gerätschaften aufgerüstet und das Übungsmaterial verstaut. \r\n\nHelmut PLANK, Kommandant','2025-06-23','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','brand'),(5,'Gemeinschaftsübung mit der FF Mühlau','uebung','Am 23.06.2025 wurden wir von der FF Mühlau zu einer Gemeinschaftsübung, mit den Thema Gefahrgutunfall eingeladen. Einmal war im Freien, beim Verladen eines LKW ein Fass mit \"Essigsäure\" umgestürzt und im Keller der Anlage, war ebenfalls ein Fass mit dem selben Inhalt umgekippt. Die FF Mühlau übernahm in beiden Fällen die Chrashbergung von Personen unter schwerem Atemschutz. Eine Atemschutztrupp unserer Einheit rüstete sich mit Schutzstufe 3 Anzügen (Chemilakenschutzanzügen) aus, während die weiteren Kameraden/Innen gemeinsam mit Kameraden/Innen der FF Mühlau die Dekontaminationsstraße aufbauten. Der SIII Trupp begab sich in den Keller, stellte das Fass auf und verdünnte mit viel Wasser die ausgeflossenen Flüssigkeit. Im Freien wurde das Verdünnen der ausgeflossenen Essigsäure von Kameraden/Innen der FF Mühlau übernommen. Am Schluss der Übung konnten wir die Kameraden/Innen der FF Mühlau noch in die Arbeitsweise bei der Dekostraße informieren bzw. schulen. Zu diesem Zwecke haben wir auch alle Anzüge, welche wir im GGF mitführen, an diesem Abend in Verwendung (S3, S2 und Einweganzüge). Wir bedanken uns recht herzlich für die Einladung und die anschließende Jause vor Ort. \r\n\nNach der Jause ging es für unsere Kameraden/Innen weiter zu einem Realeinsatz, Brand im Hochhaus. Näheres im Einsatzbericht. \r\n\nHelmut PLANK, Kommandant','2025-06-23','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48',NULL),(6,'THL Sicherungsarbeiten','einsatz','Am Sonntag den 09.03.2025 kurz nach 16:00 Uhr wurden wir auf Grund des Windes zu einem umgestürzten Bauzaun in die Pradler Straße alarmiert. LAST1 und TLFH rückten umgehend aus und stellten den Bauzaun wieder auf. Teils gebrochene Zaunelemente mussten ausgetauscht und der Zaun von der Rückseite her gesichert werden. Der Fußgängerweg in diesem Baustellenbereich wurde abgesperrt. Das restliche Material wurde gesichert in der Absperrung abgelegt. Für die Fußgänger war entlang der Hausmauer noch eine Durchgangsmöglichkeit vorhanden. Während des Einsatzes war das KLF und TF voll besetzt auf Bereitschaft in der Wache.\r\n\nHelmut PLANK, Kommandant','2025-03-09','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','technisch'),(7,'41. Jahreshauptversammlung','sonstige','41. Jahreshauptversammlung am 07.03.2025\r\n\nZur diesjährigen 41. Jahreshauptversammlung konnten wieder einige Ehrengäste begrüßt werden. Unter anderem\r\n\nv  Pfarrer und Feuerwehrkurat Paul KNEUSSL\r\n\nv  Herr Bürgermeister Ing. Mag. Johannes ANZENGRUBER\r\n\nv  Ing. Marcus WIMMER von der Berufsfeuerwehr Innsbruck\r\n\nv  das gesamte Bezirkskommando unter BFK OBR Gerhard MAYREGGER\r\n\nv  BFK a. D. OBR Albert PFEIFHOFER\r\n\nv  Ehrenmitglied und Ehrenkommandant HBI Armin PRAXMARER\r\n\nNach dem Kassabericht, dem Bericht der Jugend und der Ansprache des Kommandanten kam es zu einer Angelobung, Beförderungen und Auszeichnungen:\r\n\nv  Angelobt und zum Feuerwehrmann/frau befördert wurde FM Irmgard BRANDLHUBER\r\n\nv  Ernannt zum Probefeuerwehrmann wurden Andreas BINDER und Linhard BOYAKE\r\n\nv  Zum Hauptfeuerwehrmann wurde Patrick HEINRICH befördert\r\n\nv  Zum Hauptlöschmeister wurde Mike PELZL befördert\r\n\n    Ausgezeichnet wurden:\r\n\nv  Franz STURM für 30 Jahre Feuerwehrdienst\r\n\nv  Kurt PLANKENSTEINER für 40 Jahre Feuerwehrdienst\r\n\nv  Martin WINDBICHLER für 40 Jahre Feuerwehrdienst\r\n\nAlle anwesenden Ehrengäste bedankten sich für die erbrachten Stunden und Leistungen im abgelaufenen Jahr. Ing. WIMMER zeigte anhand eines Rechenbeispiels sogar auf, dass wir im letzten Jahr fast 140 Stunden pro Woche ehrenamtlich und für das Wohl der Bevölkerung im Dienst waren. Vom Bürgermeister wurde auch nochmals ausgeführt, dass im 6 Jahresprogramm der Stadtregierung verankert ist, dass in dieser Periode über einen Neubau der Feuerwehr Reichenau zumindest geredet und erste Planungsschritte erfolgen sollen. \r\n\nIm abgelaufenen Jahr wurden wir zu 5 Brandeinsätzen, 4 Gefahrguteinsätzen und 34 technischen Einsätze alarmiert. Hervorzuheben sind hier eine gemeldete Explosion in einer Tiefgarage, welche sich dann als PKW Brand herausstellte, die 4 Gefahrguteinsätze und der Unwetterabend am 19.07.2024, wo es Teile der Reichenau schwer erwischt hat und wir bis in die Nacht hinein mit allen Fahrzeugen und dem gesamten Wasserschadenequipment im Dienst standen. Insgesamt leisteten die Kameraden/Innen im abgelaufenen Jahr über 7200 Stunden. Auch Eigenanschaffung von Gerätschaften und Umbaumaßnahmen in der Wache im Wert von fast € 7.000.—wurden in der Ansprache vom Kommandanten dargelegt. Bedanken möchten wir uns hier auch nochmal bei unseren Gönnern der Feuerwehr Reichenau, Markus PILSER vom Autohaus PILSER, Gerhard FARBMACHER von FARBMACHER-KAFFEE und Lars GUNDOLF, dem ehemaligen Geschäftsführer vom Gasthof SANDWIRT AM INN, welcher bereits abgerissen wurde.\r\n\nBedanken möchten wir uns auch noch bei der Schützenkompanie Reichenau für die Zurverfügungstellung des Vereinsheimes und bei Traudi, Sabine und Kurt für die Bewirtung. \r\n\nAuch heuer werden die Kameraden und Kameradinnen der FF Reichenau wieder ehrenamtlich für die Bevölkerung des Schutzgebietes aber auch für die Bevölkerung der gesamten Landeshauptstadt Innsbruck da sein. \r\n\n„GOTT ZUR EHR, DEM NÄCHSTEN ZUR WEHR“','2025-03-07','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48',NULL),(8,'THL Ölspur','einsatz','Am 13.04.2022 kurz nach 19:00 Uhr wurden wir zur Unterstützung des 1. Trupp der BF Innsbruck zu einer längeren Treibstoffspur alarmiert. Die Treibstoffspur erstreckte sich von der Pradler Straße über die Reichenauer Straße / Andechsstraße / Gumppstraße bis in die Valiergasse. Von unserer Mannschaft welche mit LAST1, TLFH und GGF ausrückte wurde Bindemittel auftragen, eingekehrt und von der Kehrmaschine der Stadt Innsbruck die Abschlussreinigung der Fahrbahn vorgenommen. Um 20:00 Uhr konnte der Einsatz beendet werden. \r\n\nHelmut PLANK, Kommandant','2022-04-13','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','technisch'),(9,'3 technische Einsätze - Ölspuren','einsatz','Am 20.06.2024 um 11:40 Uhr wurden wir zur Unterstützung der BF Innsbruck zu einer Ölspur quer durch Innsbruck alarmiert. Beginnend von der Pauluskirche erstreckte sich die Ölspur in unserem Schutzgebiet schlussendlich von der Radetzkystraße - Reichenauer Straße - Pembauer Straße - Biener Straße bis zum Bahnviadukt in beiden Fahrtrichtungen. Über 300 kg Bindemittel musste von uns auftragen und eingekehrt werden. Die durch die BF bereits verständigte verständigte Kehrmaschine wurde das Bindemittel dann wieder eingekehrt. \r\n\nDer 2. Einsatz erreichte uns während des noch laufenden ersten Einsatzes in der Andechsstraße, wo bei einem reisebus die Leitung der Servolenkung eine Leck hatte. Hier wurde am Abstellplatz Bindemittel aufgebracht, damit dieser dort, bis zum Eintreffen des Servicedienstes problemlos abgestellt werden konnte. \r\n\nWährend des Auffüllens der leere Bindemittelcontainer in der BF Innsbruck, wurden wir zum 3. Einsatz, wiederum eine Ölspur, in die Franz-Fischer-Straße alarmiert. Dort war bei einem Klein-LKW das gesamte Öl der Ölwanne ausgeflossen. Die Spur reichte von der Leopoldstraße über die Michael-Gaismair-Straße, weiter in die Templstraße und Franz-Fischer-Straße. Auch wurde Bindemittel aufgetragen und eingekehrt. \r\n\nNach Beendigung aller Einsätze, wurde noch die Einsatzbereitschaft hergestellt und die Kameraden/Innen konnten nach ca. 4 Stunden wieder zu ihren Arbeitsstellen bzw. nach Hause fahren. \r\n\nIm Einsatz standen neben der Berufsfeuerwehr Innsbruck und uns, auch noch die Freiwilligen Feuerwehren Amras und Mühlau. \r\n\nHelmut PLANK, Kommandant','2024-06-20','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','technisch'),(10,'Gefahrguteinsatz','einsatz','Heute um 14:54 Uhr wurden wir gemeinsam mit der Berufsfeuerwehr Innsbruck zu einem Gefahrguteinsatz in einem Gastronomiebetrieb alarmiert. Ein 240 Liter großer CO2 Tank im Keller eines Gebäudes wurde beschädigt, wodurch das CO2 ausgetreten war. Während die Kameraden der BF die Leckage behelfsmäßig abdichteten und das CO2 kontrolliert ins Freie leiteten, bestand unsere Aufgabe darin, den Einsatzort abzusperren und die BF beim Aufbau des Absaug- und Belüftungsgerätes zu unterstützen. Nach etwas über 2 Stunden war der Einsatz für uns beendet und wir rückten wieder ein. Danke an die EL und die gesamte Mannschaft der BF für die gute Zusammenarbeit an der Einsatzstelle. \r\n\nHelmut PLANK, Kommandant','2022-04-17','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','abc'),(11,'Brand in Tiefgarage','einsatz','Am 03.02.2023 um 07:15 Uhr wurden wir gemeinsam mit der Berufsfeuerwehr Innsbruck per Sirene und Pager zu einem Kellerbrand in einem Mehrfamilienhaus alarmiert. Beim Eintreffen der BF Innsbruck stellte sich heraus, dass es sich nicht um einen Kellerbrand sondern um einen Fahrzeugbrand in der Tiefgarage handelte. Wir rückten umgehend mit Kommando und Tanklöschfahrzeug aus. Der 1. Atemschutztrupp erhielt den Auftrag sofort das Stiegenhaus und das Hauptgebäude (Bürogebäude) auf Personen und Verrauchungen zu kontrollieren. In weiterer Folge wurde dieser ATS-Trupp in die komplett verrauchte Tiefgarage beordert um dort Nachschau zu halten und Nachlöscharbeiten am brennenden Fahrzeug durchzuführen. Ein weiterer Atemschutztrupp unserer Einheit kontrollierte in weiterer Folge noch 2 weitere Stiegenhausaufgänge und der 3. ATS Trupp verblieb als Reservetrupp auf Bereitschaft. Im Laufe des Einsatzes wurden noch CO Messungen in den Stiegenhäusern und Wohnungen durchgeführt, welche alle negativ verliefen. In weiterer Folge wurde der LUF (Luftunterstützungsfahrzeug) der BF in der Tiefgarage eingesetzt und wir belüfteten gemeinsam mit der BF die 3 Stiegenhausaufgänge, so dass diese nicht durch Rauchverschleppungen verraucht werden konnte. Der 3. ATS Trupp wurde dann in ein angrenzendes Gebäude geschickt, da bei einer durchgeführten Kontrolle festgestellt wurde, dass dort das Stiegenhaus in Richtung Keller und Tiefgarage noch starke Verrauchungen aufwies. Das Stiegenhaus wurde belüftet und bis zum Eintreffen der Feuer- und Baupolizei gesperrt. Gegen 10:45 Uhr konnte unsere Einsatzmannschaft abrücken. Das TLFH und KLF wurden einsatzbereit gemacht und die Reinigungsarbeiten werden dann am Abend fortgeführt. Ein Dank noch an die Fa. M-Preis welche uns mit Kaffee und etwas Süßen verköstigte. \r\n\nAm Einsatzort: BF Innsbruck, FF Reichenau, Rotes Kreuz Innsbruck, Polizei, Stadtmagsitrat Innsbruck; \r\n\nHelmut PLANK, Kommandant','2023-02-03','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','brand'),(12,'THL - Innuferreinigung','einsatz','Am 13.04.2024 nahm, wie jedes Jahr, auch die Freiwillige Feuerwehr Reichenau an der groß angelegten Innuferreinigung teil. 12 Kameraden/innen reinigten dabei den südlichen Innuferbereich von der Tiflisbrücke bis zur Grenoblerbrücke. Laut den Kameraden/Innen wurde zwar wieder einiges an Müll gesammelt aber nicht so viel wie die letzten Jahre. Unter anderem konnte sogar ein weggeworfener, jedoch bereits sehr röstiger und verwitterter Rollstuh aufgefunden werden. Danke an die Kameraden/Innen, welche sich die Zeit für diese sehr wichtige Arbeit genommen haben. \r\n\nHelmut PLANK, Kommandant','2024-04-13','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','technisch'),(13,'Zimmerbrand','einsatz','Am 31.03.2024 um 23:19 Uhr wurden wir zur Unterstützung der Berufsfeuerwehr Innsbruck zu einem Wohnungsbrand mittels Sirene und Pager alarmiert. Nach unserem Eintreffen erhielten wir den Auftrag das total verrauchte Stiegenhaus zu kontrollieren und die Anwohner zu beruhigen. Ein weiterer Atemschutztrupp verblieb als Rettungstrupp vor dem Hauseingang. Der Brand konnte von der BF rasch unter Kontrolle gebracht, das Stiegenhaus und Wohnung belüftet werden. Im Anschluss an die Löscharbeiten konnte der Bezirksbrandermittler der Polizei die Arbeit aufnehmen. Neben der Berufsfeuerwehr und uns, waren noch das Rote Kreuz und die Polizei vor Ort. Die FF Amras besetzte derweilen ihre Wache als Bereitschaftseinheit. Nach ca. 1 Stunde konnte der Einsatz von uns beendet werden. Die FF Reichenau stand mit 4 Fahrzeugen und 24 Männer und Frauen im Einsatz. \r\n\nHelmut PLANK, Kommandant','2024-03-31','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','brand'),(14,'Brandsicherheitswache-Tuifltreffen','einsatz','Zum 10 Jahresjubiläum der \"Innsbrucker Alpentuifl\" veranstaltete der Verein ein \"Tuifltreffen\" in der Reichenau. Wir übernahmen natürlich wieder die Brandsicherheitswache bei diesem Event. Während der Auftritte der verschiedenen \"Tuiflgruppen\" kam es zu keinen nenneswerten Vorfällen und so konnten die Kameraden/Innen nach der BSW gegen 22:00 Uhr wieder einrücken. Wir waren mit 10 Mann/Frau und 2 Fahrzeugen vor Ort. Wir gratulieren den \"Innsbrucker Alpentuifl\" unter ihrem Obmann Marcel R. zu dieser großartigen Veranstaltung und zu ihrem 10 jährigen Jubiläum. \r\n\nHelmut PLANK, Kommandant','2024-11-30','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','brand'),(15,'Unterstützungseinsatz Kematen i. Tirol','einsatz','Am 12.08.2024 kurz vor Mitternacht wurden wir von der Leitstelle Tirol zu einem Unterstützungseinsatz mit unserer Großpumpe nach Kematen in Tirol alarmiert. Wir rückten mit den Fahrzeugen LAST1, dem TLFH und dem Großpumpenanhänger in Richtung Kematen aus. Vor Ort galt es dann gemeinsam mit den Kameraden der FF Lans und deren Großpumpe eine Straßenunterführung auszupumpen. Ablösen konnten wir dadurch die an der Einsatzstelle anwesenden Kameraden der FF Zirl und FF Kematen mit ihren Schmutzwasserpumpen. Kurz vor 02:30 Uhr konnten wir nach einer Grobreinigung der Ausrüstung wieder in Richtung Wache einrücken, wo die Einsatzbereitschaft wieder hergestellt wurde. Die letzten Kameraden verließen gegen 03:30 Uhr die Wache und mussten nach einer kurzen Nacht, in der Früh wieder zur Arbeit. \r\n\nHelmut PLANK, Kommandant','2024-08-12','FF Reichenau',1,'2026-04-09 11:31:48','2026-04-09 11:31:48','unterstuetzung'),(16,'Sturm über Innsbruck','einsatz','Am 10.12.2017 um 13:26 Uhr wurden wir zum 1. Einsatz an diesem Tag alarmiert. Im Bereich Langer Weg / Andechsstraße wurden durch die starken Sturmböen 2 Zelter aus den Verankerungen gerissen. Ein Zelt flog dabei über die Fahrbahn in eine angrenzende Wiese. Weiters wurde ein Lichtmasten umgeknickt. Während die Mannschaft des TLF beschäftigt war, beide Zelte zu zerlegen und zu sichern, wurde die KLF Besatzung zu einem entwurzelten Baum in die Egerdachstraße gerufen. Der Baum wurde zerlegt und der Wurzelstock mittels eines Kranes der IKB, welcher zuvor den umgeknickten Lichtmasten am Langen Weg entfernt. In der Jahnstraße wurden Dachziegel durch den starken Wind aus der Verankerung gerissen. Mittels Hubrettungsbühne der BF Innsbruck konnten die Ziegel gesichert werden. Weiter Einsätze ergaben sich noch durch umgeworfene Bauzäune und eine abgerissenen Fahne. Nach Erledigung der 6 Einsätze verblieb 1 Gruppe noch bis 16:30 Uhr auf der Wache in Bereitschaft. Es ergaben sich keine Einsätze mehr. \r\n \r\nHelmut PLANK, Kommandant','2017-12-10','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(17,'90. Geburtstag unseres Ehrenmitgliedes Rudi Krebs','sonstige','Am 06.11.2017 feierte unser Ehrenmitglied und Ehrenmitglied des Bezirksfeuerwehrverbandes Innsbruck Stadt, Alt-Vizebürgermeister Rudi KREBS seinen 90. Geburtstag. Aus diesem Grund lud der BFV Innsbruck Stadt und die Einheit Reichenau zu einer Feierstunde ein. Nach kurzen Ansprachen des Bezirksfeuerwehrkommandanten und des Einheitskommandanten, richte noch der Jubilar seine Grußworte an die anwesenden Kameraden. Nach einem gemeinsamen Abendessen standen die persönlichen Gespräche mit Rudi im Vordergrund. Auf diesem Wege möchten wir unserem Ehrenmitglied nochmals alles Gute zu seinem 90. Geburtstag wünschen.\r\n \r\nHelmut PLANK, Kommandant','2017-12-09','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20',NULL),(18,'Brandsicherheitswache beim Tuifelschauen','einsatz','Am 02.12.2017 fand im Volkshaus Reichenau das erste Tuifelschauen der Tiroler Hell Devils statt. Auf Wunsch des Veranstalters rückten 7 Mitgleider aus unserer Einheit zu dieser Brandsicherheitswache aus. Der Einsatz konnte um Mitternacht ohne Zwischenfälle beendet werden.','2017-12-02','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','brand'),(19,'Feuerwehrball 2017','sonstige','Hier einige Impressionen unseres diesjährigen Feuerwehrballs, welcher erstmals im Sandwirt stattgefunden hat.','2017-11-17','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20',NULL),(20,'Brandsicherheitswache im Pema 2','einsatz','','2017-10-21','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','brand'),(21,'Person in Notlage','einsatz','Am 17.10.2017 um 21:35 Uhr wurden wir zu einer Wohnungsöffnung auf Grund einer verunfallten Person in die Andechsstraße alarmiert. Der 1. Trupp der BF Innsbruck stieg mittels Drehleiter über ein gekipptes Fenster im 4. Stock ein und konnte so für den Rettungsdienst die Wohnungstüre öffnen. Nach der Erstversorgung halfen wir der Rettung noch beim Abtransport durch das Stiegenhaus zum Rettungsfahrzeug. Wir standen mit 1 Gruppe vor Ort im Einsatz und 2 Gruppen verblieben in der Wache auf Bereitschaft. Helmut PLANK, Kommandant','2017-10-17','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(22,'Umbau der Wache','sonstige','Auf Grund massiver Wasserschäden in den letzten Jahren, muss nun die abhängende Decke im Umkleidebereich und in der Funkkabine erneuert werden. Um hier dem Gebäudeerhalter Geld zu sparen, erklärten sich die Kameraden bereit, den Abbau und Abriss der alten Decke inklusive Deckenkonstruktion selbst zu erledigen. Heute Nachmittag trafen sich dazu 7 Kameraden in der Wache um diese Arbeiten inkl. Entsorgung zu übernehmen. Der Abbau und Reinigungsarbeiten dauerten 4 Stunden. Eine Firma wird nun ab dem 23.10.2017 eine neue Decke einbauen und in weiterer Folge werden die Räume noch ausgemalt, so dass von den Wasserschäden Gott sei Dank nichts mehr zu sehen sein wird. Auch werden in diesem Zuge die alten Lampen mit Neonröhren gegen neue LED Lampen ausgetauscht. Danke an die Kameraden, welche sich die Zeit dafür genommen haben und an Michaela und Klaus vom Gebäudeerhalter für die tolle Unterstützung.\nHelmut PLANK, Kommandant','2017-10-14','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20',NULL),(23,'Fertigstellung der ATS Werkstatt','sonstige','Jetzt ist es geschafft. Nach ca. 4 Wochen Bauzeit konnten wir nun den Atemschutzarbeitsplatz fertig stellen. Da wir seit Herbst nun die Atemschutzmasken selber reinigen, trocken und warten, war es notwendig einen Arbeitsplatz für die Atemschutzwarte zu schaffen. Aus diesem Grund haben wir im hinteren Bereich den Umkleideraum komplett umgebaut und zu einem Atemschutzarbeitsplatz ausgebaut. Ein paar kleine Arbeiten müssen noch erledigt werden, der Arbeitsplatz konnte jedoch bereits in Betrieb genommen werden. Ein großes Danke an David und Mike, welche die meisten Arbeitsstunden aufgewendet hatten aber auch an die unzähligen Helfer, welche bei diesem Umbau tatkräftig unterstützt haben. So haben unsere beiden Atemschutzwarte David und Patrick nun einen geeigneten Arbeitsplatz für ihre sehr wichtige Aufgabe. Die Gesamtkosten für diesen Umbau belaufen sich auf ca. € 6.500.--, welche komplett aus der Kameradschaftskasse investiert wurden.\nHelmut PLANK, Kommandant','2017-10-14','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20',NULL),(24,'Massiver Wasserschaden','einsatz','FW-Anford-Einsatzleiter\r\nHeute am 18.09.2017 wurden wir gegen 08:00 Uhr zur Unterstützung der BF und der FF Hötting mit der Großpumpe zu einem Wasserschaden am Mitterweg alarmiert. Eine Garage stand derart unter Wasser, dass mehrere Pumpen und die Großpumpe eingesetzt werden mussten. Der Einsatz konnte erst nach 16:00 Uhr beendet werden. Wir standen mit 12 Kameraden/Innen, dem TLFH, der Großpumpe und dem TF im Einsatz.\r\n \r\nHelmut PLANK, Kommandant','2017-09-18','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(25,'Wasserschaden am Parkplatz','einsatz','Heute am 01.09.2017 um 11:27 Uhr wurden wir zur Unterstützung der BF hinter die neue Kletterhalle, Ing.-Etzel-Straße beordert, da es dort zu einem Wasserschaden gekommen war. Beim Eintreffen konnten wir gemeinsam mit de BF den Wasserschaden beheben und gegen 12:45 Uhr wieder in die Wache einrücken. Wir blieben über Auftrag vom BO mit einer Gruppe und dem Kommando bis ca. 13:30 Uhr noch auf Bereitschaft auf der Wache.\r\n \r\nHelmut PLANK, Kommandant','2017-09-02','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(26,'Umgestürzter Bauzaun','einsatz','','2017-08-18','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(27,'Umgestürzter Bauzaun','einsatz','','2017-08-18','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(28,'Übersiedlung Kindergarten St. Paulus','sonstige','Letzten Freitag übersiedelte der Kindergarten St. Paulus von seinem vorrübergehenden Quartier in der Pirminkirche in den neu gebauten Kindergarten hinter der Pauluskirche. Auch die Kameraden/Innen der FF Reichenau halfen natürlich wieder gerne mit. Wir wünschen allen Kindergärtnerinnen und den Kindern viel Freude in ihrem neuen Heim. Helmut Plank, Kommandant','2017-08-18','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20',NULL),(29,'Umgestürzter Bauzaun','einsatz','','2017-08-08','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(30,'Unwettereinsätze in der Reichenau','einsatz','Heute, am 30.07.2017 um 19:40 Uhr wurden wir zu einem technischen Einsatz (D-THL Sicherungsarbeit) in die Reichenauer Straße alarmiert. Das Kommando und die Besatzung des Tanklöschfahrzeuges rückten umgehend zu dem 7 stöckigen Gebäude aus, wo durch den heftigen Wind, das dort gelagerte Baumaterial herum- und auch vom Dach geworfen wurde. Es wurden verschiedenste Baumaterialien am Dach gesichert. Zeitgleich wurden von der Mannschaft des TLFH 2 umgeworfene Bauzaun, auf einer Länge von ca. 80 – 100 Meter wieder aufgestellt. Die Mannschaft des KLF wurde in der Zwischenzeit zu mehreren umgeworfenen Bauzäunen (zwischen der Krzg. Rossaugasse / Langer Weg bis hinauf zur Jugendherberge in der Reichenauer Straße) beordert. Weiters wurden dann noch bei mehreren Baustellen in unserem Schutzgebiet die Bauzäune und die Verkehrsschilder wieder aufgestellt. Um 20:40 Uhr waren alle Einsätze abgearbeitet. 1 Gruppe mit dem Kommando verblieb noch bis 21:15 Uhr auf der Wache in Bereitschaft.\r\n\r\nHelmut PLANK, Kommandan','2017-07-30','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(31,'Brandmeldealarm','einsatz','','2017-07-21','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','brand'),(32,'Fahrzeugbrand in Tiefgarage','einsatz','Am 20.07.2017 um 07:26 Uhr wurden wir zur Unterstützung der BF Innsbruck zu einem Fahrzeugbrand in einer Tiefgarage in der General-Eccher-Straße alarmiert. Nach unserem Eintreffen erhielten wir den Auftrag mit einem Atemschutztrupp die gesamte Garage nach Personen abzusuchen und den Kameraden der Berufsfeuerwehr bei dem in Stellung bringen des LUF, zur Belüftung der Garage, zu unterstützen. Anschließend wurden von 3 Trupps in 3 Häusern die Wohnung auf CO Werte überprüft. Um 09:00 Uhr konnten wir von der Einsatzstelle wieder abrücken. Danke für die gute Zusammenarbeit aller am Einsatz beteiligter Einsatzorganisationen.Helmut PLANK, Kommandant','2017-07-20','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','brand'),(33,'Übung mit der FF Mühlau - Verkehrsunfall mit Gefahrengut','uebung','Am gestrigen Montag wurden wir von der FF Mühlau zu einer Gemeinschaftsübung eingeladen. Übungsszenario lautete Verkehrsunfall mit Gefahrgutbeteiligung, weshalb wir unter anderem mit unserem Gefahrgutfahrzeug (GGF) ausrückten. Die Kameraden/Innen der FF Mühlau übernahmen unter Schutzstufe 1 die Crashbergung der verunfallten Personen und deren Betreuung. In der Zwischenzeit rüsteten sich 3 Kameraden unserer Einheit mit Schutzstufe II Anzügen aus und erkundeten die Lage beim Gefahrgut-LKW. Nach Feststellung des Stoffes, wurde ein Auffangbehälter untergestellt, ein in unmittelbarer Nähe befindlicher Kanal abgedichtet und der undichte Kanister aufgestellt. Weiters wurde von den restlichen Kameraden die Deko-Straße aufgestellt. Nach Beendigung der Übung wurde den Kameraden/Innen der FF Mühlau noch die Deko-Straße und die Vorgehensweise erklärt. Wir bedanken uns bei Josef LIEBL für die Organisation dieser Übung und bei den Kameraden/Innen der FF Mühlau für den tollen, kameradschaftlichen Übungsabend.','2017-07-18','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20',NULL),(34,'Arbeitseinsatz bei den Schützen','einsatz','','2017-06-18','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(35,'Waldbrand - Übung mit der FF Arzl','uebung','Am Freitag den 16.06.2017 stand auf Einladung der FF Arzl eine Gemeinschaftsübung auf dem Programm. Thema war Wasserförderung über lange Wegstrecken, wasman wörtlich nehmen konnte. Es wurden fast 60 B-Schläuche verlegt, 2 Tanklöschfahrzeuge, 2 Tragkraftspritzen wurden eingesetzt und trotz des langen Wochenendes standen mehr als 30 Feuerwehrkameraden/Innen bei dieser Übung im Einsatz. Vom Arzler Schießstand bis zur Mühlauer Aussicht, galt es eine Wasserversorgung aufzubauen. \nNach der Übung galt es noch gemeinsam alle Schläuche und Gerätschaften aufzuräumen und die Fahrzeuge wieder einsatzbereit zu machen. Nach der Übungsnachbesprechung \nwurden wir von den Kameraden/Innen noch auf eine Jause und einen kameradschaftlichen Abend in der Wache Arzl eingeladen. So konnte die Übung nochmal in kleinen \nGruppen besprochen und die Kameradschaft zwischen den beiden Einheiten vertieft werden. Ein Dank an die Kameraden/Innen der FF Arzl für den absolut gelungenen Freitagabend. \nMit Sicherheit wird es wieder eine Gemeinschaftsübung geben, welche dann in der Reichenau stattfinden wird. \nHelmut PLANK, Kommandant','2017-06-16','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20',NULL),(36,'Großübung der Jugendfeuerwehr','uebung','Übung der Feuerwehrjugend, des Bezirksfeuerwehrverbandes Innsbruck Stadt am 10.06.2017 in Mühlau. Auch die Jugendgruppe der FF Reichenau mit 5 Jugendfeuerwehrmitgliedern und 3 Betreuern nahmen an dieser Gemeinschaftsübung teil. In Mühlau galt es einen \"Wohnhausbrand\" zu bekämpfen. Dazu mussten die Jugendlichen 2 Pumpen in Stellung und anschließend mehrere Löschrohre zum Einsatz bringen. An den Bildern kann man erkennen, dass trotz der Anstrengung alle sichtiche Spaß an dieser Großübung hatten. Dank an den Bezirksjugendsachberater Andreas und seinem Team für die Organisation dieser Übung mit anschließender \"Grillerei\". Weiterer Dank gebührt den Jugendbetreuern der Einheiten, welche mit der Jugendausbildung einen sehr wichtigen Teil in den Einheiten übernommen haben.','2017-06-10','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20',NULL),(37,'Türöffnung','einsatz','','2017-06-09','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(38,'Neuerlicher Wasserschaden im Feuerwehrhaus','einsatz','','2017-05-26','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(39,'Gefahrguteinsatz auf der A13','einsatz','Am 16.05.2017 um 08:10 Uhr wurden wir zur Unterstützung der Feuerwehren aus dem Wipptal und der BF Innsbruck zu einem LKW Brand auf der A13 bei km 011,5 im Gemeindegebiet von Schönberg alarmiert. Der LKW war mit Gefahrgut beladen, weshalb wir vom Bereitschaftsoffizier\nder BF als Gefahrguteinheit nachalarmiert wurden. Die Anfahrt erfolgte über die A12 weiter auf die A13 und ab der Mautstelle wurden wir von der\nPolizei (Landesverkehrsabteilung – ADR Gruppe) gegen die Fahrtrichtung zum Einsatzort gelotst. Nach Eintreffen bauten wir sofort die Dekontaminationsstraße auf und besetzten diese mit 4 Schutzstufe II Trägern. Weiters streuten wir vor einem großen Kanal Ölbindemittel auf um abfließende Treibstoffe und Schmiermittel zu binden, wo wir dann von 2 Kameraden der FF Patsch abgelöst wurden. \nNach der Brandbekämpfung und der Kühlung des Sattelauflegers durch die anwesenden Kräfte, bauten wir die Dekontaminationsstraße provisorisch zusammen und begleiteten gemeinsam mit der BF den Sattelaufleger mit einem anderen Zugfahrzeug zu einem nahegelegenen Parkplatz, wo dann durch eine Spezialfirma das Gefahrgut umgepumpt wird. Gegen 11:55 Uhr konnten wir von der Einsatzstelle abrücken. Nach dem Einrücken wurden die gesamte Ausrüstung noch gereinigt und wieder auf die Fahrzeuge verladen. Die FF Reichenau stand mit 15 Mann und 4 Fahrzeugen im Einsatz. Ein Dank an alle Einsatzkräfte (Polizei, Rettung und Feuerwehr)\r\n\r\nfür die ausgezeichnete Zusammenarbeit.\r\nHelmut PLANK, Kommandant','2017-05-16','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','abc'),(40,'Evakuierungsübung Mittelhauptschule Reichenau','uebung','Am Freitag den 12.05.2017 um 09:05 Uhr wurden wir zu einer Evakuierungsübung in die „Neue Mittelhauptschule“, Burghard-Breitner-Straße alarmiert. Gemeinsam mit der Drehleiter der Berufsfeuerwehr, rückten wir mit dem Tanklöschfahrzeug und dem KLF zu dieser Einsatzübung aus. Beim Eintreffen teilte mir der Direktor mit, dass es im Physik- und Chemiesaal brennt und ca. 20 Schüler vermisst werden. Die beiden Atemschutztrupps nahmen sofort eine Löschleitung vor und begaben sich auf die Personensuche. In der Zwischenzeit konnten von der Drehleiterbesatzung bereits Schüler aus dem 2. Stock mit der Drehleiter geborgen werden. Insgesamt wurden 14 Schüler mittels der Drehleiter geborgen, 7 Schüler von dem ATS-Trupps über das Stiegenhaus ins Freie gebracht und der Rettung übergeben werden. Nach Lokalisierung des Brandes wurde weiters noch der Hochleistungslüfter in Stellung gebracht, um die verrauchten Bereich wieder rauchfrei zu machen. Nach gut 1 Stunde konnte die Übung für alle Beteiligten erfolgreich beendet werden. Im Anschluss an die Übung fand mit den Verantwortlichen der Schule noch eine Nachbesprechung statt. Danke an die Kameraden/Innen der Einheit, welche sich für diese, für die Schule sehr wichtige Evakuierungsübung, frei genommen hatten.\r\n\r\nHelmut PLANK, Kommandant','2017-05-12','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20',NULL),(41,'Waldbrand am Hechenberg','einsatz','','2017-05-11','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','brand'),(42,'Kellerbrand Reichenauer Str.','einsatz','Am 02.05.2017 um 12:40 Uhr wurden wir zur Unterstützung der BF Innsbruck zu einem Kellerbrand in die Reichenauer Straße beordert.\nBei unserem Eintreffen war die BF bei der Erkundung in den verwinkelten und stark verrauchten Kellergängen. Der Brand, es handelte sich um einen Kleinbrand, konnte dann rasch von der BF gefunden und mit einem Feuerlöscher gelöscht werden. Von uns wurde ein Reserve-Atemschutztrupp gestellt und die Kellergänge mit dem Hochleistungslüfter belüftet. Kurz nach 13:30 Uhr rückten wir von der Einsatzstelle ab und die Kameraden/Innen fuhren wieder zu ihren Arbeitsstellen. Ein Dank gilt hier auch einmal an die Arbeitgeber, welche in der Zeit der Einsätze auf ihre Mitarbeiter verzichten.\r\n \r\nHelmut PLANK, Kommandant','2017-05-02','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','brand'),(43,'Ertrinkungsnotfall im Inn','einsatz','Am 24.04.2017 um 23:38 Uhr wurden zur Unterstützung der BF und der FF Wilten, die Freiwilligen Feuerwehren Mühlau, Neu Arzl und wir alarmiert.\nAlarmierungsgrund war ein gemeldeter Ertrinkungsnotfall (Person in Wasser) im Inn. Unsere Aufgabe bestand darin von der Grenobler Brücke aus, in beiden Richtungen das südliche Innufer auszuleuchten, zu beobachten und weiters das südliche Innufer abzusuchen. Die Ausleuchtung wurde mittels 5 a. 1000 Watt Scheinwerfern, 1 Akkuscheinwerfer und je einem Lichtmasten des TLFH und GGF durchgeführt und die Absuche des südlichen Innufers vom Sillzwickel bis zur New Orlines Brücke übernahmen 5 Trupps zu Fuß mit Handlampen. Gegen 00:45 Uhr wurde der Einsatz ergebnislos abgebrochen und die Mannschaft rückte wieder ins Gerätehaus ein.\r\n\r\nHelmut PLANK, Kommandant','2017-04-24','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(44,'Wasserschaden im Feuerwehrhaus','einsatz','','2017-04-20','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(45,'Wohnungsbrand in der Reichenau','einsatz','Am 18.04.2017 um 07:29 Uhr wurde die BF Innsbruck zu einem Brandmeldealarm in die General-Eccher-Straße alarmiert. Während der Anfahrt wurde gemeldet, dass es sich tatsächlich um ein Brandgeschehen handeln dürfte, woraufhin wir vom BO um 07:33 Uhr zur Unterstützung nachalarmiert wurden.\r\nBei unserem Eintreffen war der Brand bereits gelöscht und wir erhielten den Auftrag in der Brandwohnung des Löschwasser aufzusaugen und abzupumpen, um einem etwaigen Wasserschaden vorzubeugen. Gegen 08:30 Uhr konnten wir von der Einsatzstelle wieder abrücken. Insgesamt befanden sich 14 Kameraden/Innen\r\n\r\nim Einsatz bzw. auf Bereitschaft in der Wache.\r\nHelmut PLANK, Kommandant','2017-04-18','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','brand'),(46,'Ölspur auf der Reichenaustraße','einsatz','Am 4.4. wurden wir zu einer Ölspur in der Reichenauer Straße alarmiert. Die Spur zog sich vom Bahnhof bis in die Rossaugasse. Die BF war ebenfalls mit 1 Gruppe alarmiert welche vom Bahnhof bis zur Krzg. mit der Pembaurstraße und wir dann weiter bis zur Rossaugasse die Ölspur beseitigten. Nach knapp 2 Stunden war der Einsatz beendet. Helmut PLANK, Kommandant','2017-04-04','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(47,'Person in Notlage','einsatz','Auf Grund eines großflächigen Stromausfalles im Stadtgebiet von Innsbruck wurde auch unsere Einheit alarmiert. Im Haus Hunoldstraße 15 soll eine Person im Lift eingeschlossen worden sein. Bei der Nachschau konnte keine Person in den beiden Liften festgestellt werden, die Lifte funktionierten einwandfrei. Über Auftrag wurde die Einsatzbereitschaft noch bis 16:20 Uhr aufrecht erhalten. Helmut PLANK, Kommandant','2017-01-31','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','technisch'),(48,'Wohnungsbrand mit eingeschlossenen Peronen','einsatz','Am 28.01.2017 um 11:22 Uhr wurden wir und die FF Amras durch den EL der BF Innsbruck zu einem ausgedehnten Wohnungsbrand alarmiert. 1 ATS-Trupp kontrollierte die darüber liegenden Wohnungen und das Stiegenhaus auf verletzte oder eingeschlossene Personen. Weiters wurde die Brandbekämpfung in der Wohnung unterstützt. Ein weiterer ATS-Trupp kontrollierte den Kellerbereich, wurde anschließend zur Belüftung des Dachgeschoßes eingesetzt und vor dem Haus wurde ein weiterer Lüfter in Stellung gebracht. Ein 3. ATS-Trupp blieb als Reservetrupp in Bereitschaft. Die Putzabplatzungen im Stiegenhaus wurden entfernt bzw. abgeschlagen und das Stiegenhaus vom Schutt frei geräumt. Weiters wurde in der Brandwohnung die Holzdecke und ein Holzverbau abgebaut und mit der Wärmebildkamera Kontrollen durchgeführt. Leider ist bei diesem Wohnungsbrand eine Person verstorben und weitere Personen verletzt worden. Unser tieftes Mitgefühl gilt den Verwandten und Bekannten des Opfers. Die letzten Kameraden/Innen rückten nach 7 Stunden um 18:30 Uhr von der Einsatzstelle ab. Wir möchten uns noch bei der ausgezeichneten Zusammenarbeit mit den Kameraden/In der BF Innsbruck und der FF Amras bedanken. Helmut PLANK, Kommandant','2017-01-28','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','brand'),(49,'Brand einer Mülldeponie','einsatz','Bereits am Vormittag des 24.01.2017 wurde die BF Innsbruck und die FF Wilten zu einem Brand in einer Lagerhalle, wo Müll zur Weiterverarbeitung gelagert wird, alarmiert. Um 13:29 Uhr wurden wir mit dem Tanklöschfahrzeug zur Ablöse der FF Wilten alarmiert. Wir rückten mit insgesamt 10 Kameraden/Innen zu dem Einsatz aus und übernahmen die Löscharbeiten mit insgesamt 3 C-Strahlrohren. Um 17:30 Uhr konnten wir vom Einsatz wieder abrücken. Helmut PLANK, Kommandant','2017-01-24','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','brand'),(50,'Brandsicherheitswache beim Brauchtumsschauen','einsatz','','2017-01-14','FF Reichenau',1,'2026-09-14 12:55:20','2026-09-14 12:55:20','brand');
